import { Router } from 'express';
import { randomUUID } from 'node:crypto';
import { fail, route, integer } from './errors.js';
import { discountFor } from './discounts.js';
export function totals(subtotalCents, discountCents=0) {
  if(!Number.isSafeInteger(subtotalCents)) fail(400,'INVALID_INPUT','Cart total exceeds integer range');
  const net=subtotalCents-discountCents;
  const taxCents=Math.floor((net*8+50)/100);
  return {subtotalCents,discountCents,taxCents,totalCents:net+taxCents};
}
export class Carts {
  constructor(store) {this.store=store;this.items=new Map();}
  get(id) {const cart=this.items.get(id);if(!cart)fail(404,'NOT_FOUND','Cart not found');return cart;}
  create() {const cart={id:randomUUID(),items:[],discountCode:null,createdAt:new Date().toISOString()};this.items.set(cart.id,cart);return cart;}
  async view(cart) {
    const products=await this.store.read('products');
    const items=cart.items.map(line=>{const p=products.find(p=>p.id===line.productId);if(!p)fail(404,'NOT_FOUND','Cart product not found');return {productId:p.id,name:p.name,priceCents:p.priceCents,quantity:line.quantity,lineTotalCents:p.priceCents*line.quantity};});
    const subtotalCents=items.reduce((sum,item)=>sum+item.lineTotalCents,0);
    const discountCents=await discountFor(this.store,cart.discountCode,subtotalCents);
    return {id:cart.id,items,...totals(subtotalCents,discountCents),discountCode:cart.discountCode};
  }
}
export function cartRoutes(carts) {
  const router=Router();
  router.post('/carts',route(async(req,res)=>res.status(201).json(await carts.view(carts.create()))));
  router.get('/carts/:id',route(async(req,res)=>res.json(await carts.view(carts.get(req.params.id)))));
  router.post('/carts/:id/items',route(async(req,res)=>{
    const cart=carts.get(req.params.id);const {productId,quantity}=req.body;
    if(typeof productId!=='string'||!productId)fail(400,'INVALID_INPUT','productId is required');
    integer(quantity,1,99,'quantity');
    const product=(await carts.store.read('products')).find(p=>p.id===productId);if(!product)fail(404,'NOT_FOUND','Product not found');
    const line=cart.items.find(l=>l.productId===productId);const next=(line?.quantity||0)+quantity;
    integer(next,1,99,'quantity');if(next>product.stock)fail(409,'OUT_OF_STOCK',product.name+' has insufficient stock');
    if(line)line.quantity=next;else cart.items.push({productId,quantity});
    res.json(await carts.view(cart));
  }));
  router.patch('/carts/:id/items/:productId',route(async(req,res)=>{
    const cart=carts.get(req.params.id);const quantity=integer(req.body.quantity,0,99,'quantity');
    const line=cart.items.find(l=>l.productId===req.params.productId);if(!line)fail(404,'NOT_FOUND','Cart line not found');
    if(quantity===0)cart.items=cart.items.filter(l=>l!==line);else {
      const p=(await carts.store.read('products')).find(p=>p.id===line.productId);
      if(quantity>p.stock)fail(409,'OUT_OF_STOCK',p.name+' has insufficient stock');line.quantity=quantity;
    }
    res.json(await carts.view(cart));
  }));
  router.delete('/carts/:id/items/:productId',route(async(req,res)=>{
    const cart=carts.get(req.params.id);const before=cart.items.length;cart.items=cart.items.filter(l=>l.productId!==req.params.productId);
    if(cart.items.length===before)fail(404,'NOT_FOUND','Cart line not found');res.json(await carts.view(cart));
  }));
  return router;
}

import express from 'express';
import { Store } from './store.js';
import { catalogRoutes } from './catalog.js';
import { Carts, cartRoutes } from './cart.js';
import { discountRoutes } from './discounts.js';
import { checkoutRoutes } from './checkout.js';
import { orderRoutes } from './orders.js';
export function createApp({ dataDir = new URL('../data/', import.meta.url).pathname } = {}) {
  const app = express();
  const store = new Store(dataDir);
  const carts = new Carts(store);
  app.use(express.json());
  app.get('/health', (req, res) => res.json({ status: 'ok' }));
  app.use('/api', catalogRoutes(store));
  app.use('/api', cartRoutes(carts));
  app.use('/api', discountRoutes(carts));
  app.use('/api', checkoutRoutes(store,carts));
  app.use('/api', orderRoutes(store));
  app.use(express.static(new URL('../dist/', import.meta.url).pathname));
  app.use((req, res) => res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Route not found' } }));
  app.use((error, req, res, next) => res.status(error.status || 400).json({ error: { code: error.code || 'INVALID_INPUT', message: error.message } }));
  return app;
}
